import copy

def deep_merge(a, b):
    """
    Głęboko łączy dwa słowniki 'a' i 'b'.

    Reguły:
    - Dla zagnieżdżonych słowników: połączenie rekurencyjne.
    - Dla list: zastąpienie całej listy z 'b' na miejsce listy z 'a'.
    - W innych konfliktach (klucz istnieje tylko w 'b' lub wartości są niezgodne): 
      wartość z 'b' wygrywa.
    - Wynik jest głęboką kopią: modyfikacje wyniku nie wpływają na wejścia.

    Parametry:
        a (dict | list | any): Pierwszy obiekt do scalenia.
        b (dict | list | any): Drugi obiekt do scalenia (ma priorytet).

    Zwraca:
        dict | list | any: Głęboka kopia scalonego obiektu.
    """

    # Jeśli 'a' nie jest słownikiem, a 'b' jest słownikiem, zwracamy głęboką kopię 'b'.
    if not isinstance(a, dict) and isinstance(b, dict):
        return copy.deepcopy(b)

    # Jeśli 'a' jest słownikiem, a 'b' nie jest, zwracamy głęboką kopię 'a'.
    if isinstance(a, dict) and not isinstance(b, dict):
        return copy.deepcopy(a)

    # Jeśli oba są słownikami, scalamy je rekurencyjnie.
    if isinstance(a, dict) and isinstance(b, dict):
        result = {}
        # Dodajemy wszystkie klucze z 'a' (głęboka kopia wartości)
        for key in a:
            if key in b:
                # Konflikt klucza: rekurencyjne scalanie
                result[key] = deep_merge(a[key], b[key])
            else:
                # Klucz tylko w 'a': głęboka kopia
                result[key] = copy.deepcopy(a[key])

        # Dodajemy klucze z 'b', które nie są w 'a' (głęboka kopia)
        for key in b:
            if key not in result:
                result[key] = copy.deepcopy(b[key])

        return result

    # Jeśli oba są listami, zgodnie z instrukcją "listy zastępują w całości", 
    # zwracamy głęboką kopię 'b'.
    if isinstance(a, list) and isinstance(b, list):
        return copy.deepcopy(b)

    # W przypadku innych typów danych (liczby, stringi, None itp.) lub gdy jeden jest listą, a drugi nie słownikiem/listą:
    # Zgodnie z zasadą "w innych konfliktach wygrywa b", zwracamy głęboką kopię 'b'.
    return copy.deepcopy(b)
