from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 0:
            raise ValueError("Capacity cannot be negative.")
        self.capacity = capacity
        # OrderedDict zachowuje kolejność wstawienia elementów.
        # Najdawniej użyty element znajduje się na początku (left).
        self.cache = OrderedDict()

    def get(self, key: int) -> int:
        if key in self.cache:
            # Przenosimy klucz na koniec, aby oznaczyć go jako najnowo użyty.
            # move_to_end przesuwa element do końca listy, zachowując O(1).
            self.cache.move_to_end(key)
            return self.cache[key]
        else:
            return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            # Aktualizujemy wartość i przenosimy klucz na koniec.
            self.cache[key] = value
            self.cache.move_to_end(key)
        else:
            # Dodajemy nowy element.
            self.cache[key] = value

            # Jeśli pojemność została przekroczona, usuwamy najdawniej użyty element (pierwszy).
            if len(self.cache) > self.capacity:
                # popitem(last=False) usuwa i zwraca pierwszy element (najstarszy), co jest O(1).
                self.cache.popitem(last=False)
