def merge_intervals(intervals):
    if not intervals:
        return []

    # Walidacja i kopia danych (aby nie modyfikować wejścia)
    processed_intervals = []
    for interval in intervals:
        if len(interval) != 2:
            raise ValueError("Each interval must be a list of two elements.")
        start, end = interval
        if start > end:
            raise ValueError("Start of interval must be less than or equal to end.")
        processed_intervals.append([start, end])

    # Sortowanie po pierwszym elemencie (start)
    processed_intervals.sort(key=lambda x: x[0])

    merged = []
    for current in processed_intervals:
        if not merged:
            merged.append(current)
        else:
            last_merged = merged[-1]
            # Jeśli początek bieżącego przedziału jest <= końcowi ostatniego scalonego
            if current[0] <= last_merged[1]:
                # Scalamy przedziały, aktualizując koniec na większy z obu
                last_merged[1] = max(last_merged[1], current[1])
            else:
                # Dodajemy jako nowy przedział
                merged.append(current)

    return merged
