import csv
import io
from decimal import Decimal
from typing import Dict

def csv_totals(text: str) -> Dict[str, Decimal]:
    f = io.StringIO(text.strip())
    reader = csv.DictReader(f)
    totals = {}

    for row in reader:
        category = row.get('category')
        amount_str = row.get('amount')

        if category is None or amount_str is None:
            continue

        if category.strip() == "" and amount_str.strip() == "":
            continue

        try:
            amount = Decimal(amount_str)
        except (ValueError, TypeError, ArithmeticError):
            # Note: ArithmeticError is not imported, but Decimal() 
            # raises InvalidOperation which is a subclass of ArithmeticError.
            # Standard ValueError is usually sufficient for bad strings.
            raise ValueError(f"Invalid amount: {amount_str}")

        if category in totals:
            totals[category] += amount
        else:
            totals[category] = amount

    return totals
