import heapq

def topo_sort(graph: dict[str, list[str]]) -> list[str]:
    in_degree = {}
    # Inicjalizacja stopni wejściowych dla wszystkich wierzchołków
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        for v in neighbors:
            all_nodes.add(v)

    for node in all_nodes:
        in_degree[node] = 0

    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    # Kolejka priorytetowa dla leksykograficznego wyboru
    queue = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)

        if u in graph:
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    heapq.heappush(queue, v)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
