    merged = []
    for interval in valid:
        start, end = interval
        if not merged:
            merged.append([start, end])
        else:
            last = merged[-1]
            # Merge if overlapping or touching
            if start <= last[1]:
                last[1] = max(last[1], end)
            else:
                merged.append([start, end])

    return merged
