def csv_totals(text: str) -> dict[str, Decimal]:
    reader = csv.DictReader(io.StringIO(text), fieldnames=None)
    # Ensure header is exactly category,amount
    header = reader.fieldnames
    if header is None:
        return {}
    # Normalize header names (strip whitespace)
    header = [h.strip() if h else h for h in header]
    if header != ['category', 'amount']:
        # Try to find the right columns
        if 'category' not in header or 'amount' not in header:
            raise ValueError("CSV must have headers 'category' and 'amount'")

    totals: dict[str, Decimal] = {}
    for row in reader:
        # Skip empty rows (all values None or empty)
        if row is None:
            continue
        # Check if row is empty
        values = list(row.values())
        if all(v is None or (isinstance(v, str) and v.strip() == '') for v in values):
            continue

        category = row.get('category')
        amount_str = row.get('amount')

        if category is None or amount_str is None:
            continue

        category = category.strip()
        amount_str = amount_str.strip()

        if category == '' and amount_str == '':
            continue

        try:
            amount = Decimal(amount_str)
        except (InvalidOperation, ValueError) as e:
            raise ValueError(f"Invalid amount: {amount_str!r}") from e

        totals[category] = totals.get(category, Decimal('0')) + amount

