def topo_sort(graph):
    # Tworzymy kopię grafu, aby nie modyfikować oryginalnego
    graph_copy = {u: list(v) for u, v in graph.items()}

    # Znajdujemy wszystkie wierzchołki, które występują w grafie (jako klucze lub wartości)
    all_nodes = set(graph_copy.keys())
    for neighbors in graph_copy.values():
        all_nodes.update(neighbors)

    # Inicjalizujemy stopnie wejściowe
    in_degree = {node: 0 for node in all_nodes}
    for u in graph_copy:
        for v in graph_copy[u]:
            in_degree[v] += 1

    # Inicjalizujemy kolejkę z wierzchołkami o stopniu wejściowym 0
    queue = []
    for node in all_nodes:
        if in_degree[node] == 0:
            queue.append(node)

    # Sortujemy kolejkę leksykograficznie
    queue.sort()

    topo_order = []

    while queue:
        # Wybieramy leksykograficznie najmniejszy dostępny wierzchołek
        u = queue.pop(0)
        topo_order.append(u)

        # Przeglądamy sąsiadów u
