    # Tworzymy kopię grafu, aby nie modyfikować oryginalnego
    graph_copy = {u: list(v) for u, v in graph.items()}

    # Znajdujemy wszystkie wierzchołki, które występują w grafie (jako klucze lub w listach sąsiadów)
    all_nodes = set(graph_copy.keys())
    for neighbors in graph_copy.values():
        all_nodes.update(neighbors)

    # Inicjalizujemy stopnie wejściowe dla wszystkich wierzchołków
    in_degree = {node: 0 for node in all_nodes}
    for u in graph_copy:
        for v in graph_copy[u]:
            in_degree[v] += 1

    # Kolejka priorytetowa (używamy listy i sortujemy, ponieważ nie mamy heapq z priorytetem leksykograficznym)
    available = []
    for node in all_nodes:
        if in_degree[node] == 0:
            available.append(node)
    available.sort()

    topo_order = []

    while available:
        # Wybieramy leksykograficznie najmniejszy dostępny wierzchołek
        u = available.pop(0)
        topo_order.append(u)

        # Przeglądamy sąsiadów u
        for v in graph_copy.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                # Wstawiamy v w odpowiednie miejsce, aby zachować kolejność leksykograficzną
                inserted = False
                for i in range(len(available)):
                    if v < available[i]:
                        available.insert(i, v)
                        inserted = True
                        break
                if not inserted:
                    available.append(v)

    # Sprawdzamy, czy wszystkie wierzchołki zostały uwzględnione (czy nie ma cyklu)
    if len(topo_order) != len(all_nodes):
        raise ValueError("Graph contains a cycle")

    return topo_order

