        for v in neighbors:
            vertices.add(v)

    # Zbuduj listę sąsiedztwa i stopnie wejściowe
    adj: dict[str, list[str]] = {v: [] for v in vertices}
    in_degree: dict[str, int] = {v: 0 for v in vertices}

