def merge_intervals(intervals):
    if not intervals:
        return []

    # Validate and create a copy of valid intervals
    valid = []
    for interval in intervals:
        if len(interval) != 2:
            raise ValueError("Each interval must have exactly two elements")
        start, end = interval
        if start > end:
            raise ValueError(f"Invalid interval: start ({start}) > end ({end})")
        valid.append([start, end])

    # Sort by start, then by end
    valid.sort(key=lambda x: (x[0], x[1]))

    # Merge intervals
    merged = []
    for interval in valid:
        start, end = interval
        if not merged:
            merged.append([start, end])
        else:
            last = merged[-1]
            # Merge if overlapping or touching
            if start <= last[1]:
                last[1] = max(last[1], end)
            else:
                merged.append([start, end])

    return merged
